class TestGetCodeFromMetaai(unittest.TestCase):

    def test_valid_inputs(self):
        prompt = 'Hello world!'
        max_tokens = 320
        temperature = 0.6
        encoded_data = get_code_from_metaai(prompt, max_tokens, temperature)
        self.assertIsNotNone(encoded_data)

    def test_invalid_inputs(self):
        prompt = 'Hello world!'
        max_tokens = '320'
        temperature = 0.6
        with self.assertRaises(TypeError):
            get_code_from_metaai(prompt, max_tokens, temperature)

    def test_max_tokens(self):
        prompt = 'Hello world!'
        max_tokens = 320
        temperature = 0.6
        encoded_data = get_code_from_metaai(prompt, max_tokens, temperature)
        self.assertEqual(len(encoded_data), max_tokens)

    def test_temperature(self):
        prompt = 'Hello world!'
        max_tokens = 320
        temperature = 0.6
        encoded_data = get_code_from_metaai(prompt, max_tokens, temperature)
        self.assertEqual(encoded_data[-1], '.')

    def test_prompt_removal(self):
        prompt = 'Hello world!'
        max_tokens = 320
        temperature = 0.6
        encoded_data = get_code_from_metaai(prompt, max_tokens, temperature)
        self.assertNotIn(prompt, encoded_data)

    def test_response_parsing(self):
        prompt = 'Hello world!'
        max_tokens = 320
